export function getProduct(slug: string) { return products.find((p) => p.slug === slug); }
export const buildKits = () => products.filter((p) => p.pieces > 0);
export const readyBuilt = () => products.filter((p) => p.pieces === 0);
export function isReadyBuilt(p: Product) { return p.pieces === 0; }

export function getBestSellers() { return products.filter((p) => p.bestSeller); }
export function getByCategory(category: Category) { return products.filter((p) => p.category === category); }

export interface CategoryMeta { name: Category; slug: string; blurb: string; from: string; to: string; }

export const categories: CategoryMeta[] = [
  { name: "Block Cars", slug: "block-cars", blurb: "Brick-built supercars you snap together yourself.", from: "#FF2D20", to: "#7a0d06" },
  { name: "Die-Cast Cars", slug: "die-cast-cars", blurb: "Pre-built metal models in 1:24 & 1:32 scale.", from: "#0066FF", to: "#062a66" },
  { name: "RC Cars", slug: "rc-cars", blurb: "Build it, then drive it — remote-control brick cars.", from: "#1f6f3f", to: "#0c2a18" },
  { name: "Monuments", slug: "monuments", blurb: "Landmark architecture, brick by brick.", from: "#C9A24B", to: "#3a2f0a" },
];

export function categoryCount(name: Category) { return products.filter((p) => p.category === name).length; }

/** First real product photo for a category (for tiles/galleries). */
export function categoryImage(name: Category): string | undefined {
  const inCat = products.filter((p) => p.category === name && p.images[0]?.url?.startsWith("http"));
  return (inCat[0] ?? products.find((p) => p.images[0]?.url?.startsWith("http")))?.images[0]?.url;
}

/** A spread of real product photos for showcase galleries. */
export function galleryImages(count = 8): { url: string; name: string; color: string }[] {
  return products
    .filter((p) => p.images[0]?.url?.startsWith("http"))
    .slice(0, count)
    .map((p) => ({ url: p.images[0].url, name: p.name, color: p.bodyColor }));
}